# Regenerates docs/banner.png (needs: pip install cairosvg fonttools; Lato + Noto Sans CJK fonts)
import math, random, cairosvg
random.seed(7)
def blob(cx, cy, r, seed, col, drips=3):
    rnd = random.Random(seed); pts = []; n = 64
    ph = [rnd.uniform(0, 6.28) for _ in range(3)]
    for i in range(n):
        a = i / n * 2 * math.pi
        rr = r * (1 + 0.10 * math.sin(3 * a + ph[0]) + 0.06 * math.sin(5 * a + ph[1]) + 0.035 * math.sin(9 * a + ph[2]))
        pts.append((cx + math.cos(a) * rr, cy + math.sin(a) * rr))
    # smooth closed path (Catmull-Rom -> Bezier)
    d = f"M{pts[0][0]:.1f} {pts[0][1]:.1f}"
    for i in range(n):
        p0, p1, p2, p3 = pts[i - 1], pts[i], pts[(i + 1) % n], pts[(i + 2) % n]
        c1 = (p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6); c2 = (p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6)
        d += f" C{c1[0]:.1f} {c1[1]:.1f} {c2[0]:.1f} {c2[1]:.1f} {p2[0]:.1f} {p2[1]:.1f}"
    s = f'<path d="{d}Z" fill="{col}" stroke="#111" stroke-width="7"/>'
    s += f'<ellipse cx="{cx - r*0.32:.1f}" cy="{cy - r*0.38:.1f}" rx="{r*0.22:.1f}" ry="{r*0.11:.1f}" fill="#fff" opacity=".35" transform="rotate(-25 {cx - r*0.32:.1f} {cy - r*0.38:.1f})"/>'
    for k in range(drips):
        a = rnd.uniform(0, 6.28); dd = r * rnd.uniform(1.18, 1.5); rr = r * rnd.uniform(0.07, 0.15)
        s += f'<circle cx="{cx + math.cos(a)*dd:.1f}" cy="{cy + math.sin(a)*dd:.1f}" r="{rr:.1f}" fill="{col}" stroke="#111" stroke-width="5"/>'
    return s
